// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 feeRate) public {
        // feeRate is fuzzed over the full uint16 range; we restrict only to admissible input
        // that would not revert with FeeRateTooHigh in the reference (0..5000).
        // The property is: feeRate <= 5000 after initialize.
        vm.assume(feeRate <= 5000);
        // provide dummy arguments; only feeRate matters for the property
        c.initialize(
            address(this),
            address(this),
            0,
            0,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );
        assertTrue(c.feeRate() <= 5000);
    }
}
